import{_ as a,o as e,c as r,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Fuso horário","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/time-zone.md","filePath":"pt-BR/guide/time-zone.md"}'),i={name:"pt-BR/guide/time-zone.md"};function t(n,o,u,d,l,m){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="fuso-horario" tabindex="-1">Fuso horário <a class="header-anchor" href="#fuso-horario" aria-label="Permalink to &quot;Fuso horário&quot;">​</a></h1><p>O Orbit guarda todos os horários em UTC e mostra cada um no fuso que você escolher: um para a instalação, e um para cada pessoa que quiser outro.</p><h2 id="installation" tabindex="-1">O relógio do Orbit <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;O relógio do Orbit {#installation}&quot;">​</a></h2><p>O fuso da instalação é perguntado na primeira execução, com o fuso do navegador sugerido, e fica em <strong>Configurações → Geral → Fuso horário</strong>, em <strong>O relógio do Orbit</strong>. Só um administrador muda. Até alguém mudar, o Orbit usa UTC.</p><p>É o fuso em que o Orbit escreve horários quando ninguém está olhando o console:</p><ul><li>notificações no Slack, no Discord e por email, que agora dizem o fuso, como em <code>14:00 (America/Sao_Paulo)</code>;</li><li>emails de convite;</li><li>a status page pública;</li><li>o padrão dos agendamentos novos, descrito abaixo.</li></ul><p>Mudar o fuso nunca mexe num agendamento que já existe.</p><h2 id="yours" tabindex="-1">O seu relógio <a class="header-anchor" href="#yours" aria-label="Permalink to &quot;O seu relógio {#yours}&quot;">​</a></h2><p>Cada pessoa pode escolher o próprio fuso no mesmo card, em <strong>O seu relógio</strong>. Isso muda só o que ela vê: todas as datas e horários do console, inclusive os dias da atividade. A escolha fica na conta, então acompanha você em qualquer navegador. Deixe em <strong>Seguir o Orbit</strong> para ver o fuso da instalação.</p><h2 id="schedules" tabindex="-1">Agendamentos <a class="header-anchor" href="#schedules" aria-label="Permalink to &quot;Agendamentos {#schedules}&quot;">​</a></h2><p>Cada agendamento guarda o próprio fuso, então ele é lido do mesmo jeito por quem quer que olhe:</p><ul><li><strong>Backups e testes de restauração:</strong> o fuso da política, oferecido como o fuso da instalação numa política nova. Agendamentos salvos antes de o Orbit ter fuso continuam em UTC.</li><li><strong>Jobs:</strong> o fuso do job, escolhido junto com a expressão cron ao criar o job ou nas configurações dele. Um job novo recebe o fuso da instalação; jobs criados antes desta configuração existir rodam em UTC e dizem isso.</li></ul><p>Os agendamentos acompanham o horário de verão: um horário que o relógio pula roda quando o relógio avança.</p><h2 id="utc" tabindex="-1">O que continua em UTC <a class="header-anchor" href="#utc" aria-label="Permalink to &quot;O que continua em UTC {#utc}&quot;">​</a></h2><p>A API, o banco de dados, os logs no servidor e a CLI continuam em UTC, para que uma exportação ou uma linha de log seja lida igual em qualquer máquina. O fuso só muda como o Orbit escreve horários para as pessoas.</p>',15)])])}const h=a(i,[["render",t]]);export{p as __pageData,h as default};
